package demo.study;

import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;

public final class ConversationMemory {
    private final Map<String, List<String>> conversations = new HashMap<>();

    public void append(String key, String message) {
        conversations.computeIfAbsent(key, ignored -> new ArrayList<>()).add(message);
    }

    public List<String> load(String key) {
        return conversations.getOrDefault(key, List.of());
    }
}

package demo.study;

public interface CurrentUserContext {
    Long getUserId();
    boolean isAdmin();
}

package demo.study;

import java.util.ArrayList;
import java.util.List;

public final class FakeOrderService implements OrderService {
    private final List<OrderSummary> orders = List.of(
        new OrderSummary(1L, 1001L, "接口练习册", "PAID"),
        new OrderSummary(2L, 1002L, "集合练习册", "CREATED")
    );

    @Override
    public List<OrderSummary> listMyOrders(Long currentUserId) {
        if (currentUserId == null) throw new IllegalArgumentException("身份不能为空");
        List<OrderSummary> result = new ArrayList<>();
        for (OrderSummary order : orders) {
            if (currentUserId.equals(order.buyerId())) { result.add(order); }
        }
        return result;
    }
}

package demo.study;

import java.util.List;

public interface OrderService {
    List<OrderSummary> listMyOrders(Long currentUserId);
}

package demo.study;

import java.util.List;

public final class OrderTools {
    private final CurrentUserContext currentUserContext;
    private final OrderService orderService;

    public OrderTools(CurrentUserContext currentUserContext, OrderService orderService) {
        this.currentUserContext = currentUserContext;
        this.orderService = orderService;
    }

    public ToolResult<List<OrderSummary>> listMyOrders() {
        Long currentUserId = currentUserContext.getUserId();
        if (currentUserId == null) {
            return ToolResult.failure("UNAUTHORIZED", "请先登录");
        }
        List<OrderSummary> orders = orderService.listMyOrders(currentUserId);
        return ToolResult.success(orders);
    }
}

package demo.study;

import java.util.Map;

public final class ToolArgumentValidator {
    public ToolResult<Void> validate(String toolName, Map<String, Object> arguments) {
        if ("list_my_orders".equals(toolName)) {
            if (arguments == null) {
                return ToolResult.failure("MISSING_ARGUMENT", "请传入参数对象");
            }
            if (!arguments.isEmpty()) {
                return ToolResult.failure("UNKNOWN_ARGUMENT", "此工具不接受任何参数");
            }
            return ToolResult.success(null);
        }
        return ToolResult.failure("UNKNOWN_TOOL", "工具未登记");
    }
}

package demo.study;

import java.util.Map;

public final class ToolDispatcher {
    private final ToolArgumentValidator validator;
    private final OrderTools orderTools;

    public ToolDispatcher(ToolArgumentValidator validator, OrderTools orderTools) {
        this.validator = validator;
        this.orderTools = orderTools;
    }

    public ToolResult<?> dispatch(String toolName, Map<String, Object> arguments) {
        try {
            ToolResult<Void> validation = validator.validate(toolName, arguments);
            if (!validation.success()) { return validation; }
            if ("list_my_orders".equals(toolName)) { return orderTools.listMyOrders(); }
            return ToolResult.failure("UNKNOWN_TOOL", "工具未登记");
        } catch (RuntimeException failure) {
            return ToolResult.failure("INTERNAL_ERROR", "工具执行失败");
        }
    }
}

package demo.study;

public record ToolResult<T>(boolean success, String code, String message, T data) {
    public static <T> ToolResult<T> success(T data) {
        return new ToolResult<>(true, "OK", "", data);
    }
    public static <T> ToolResult<T> failure(String code, String message) {
        return new ToolResult<>(false, code, message, null);
    }
}
